def count_unique_xor_triplets(nums):
    # Set to store all unique triplet XOR values
    seen = set()
    n = len(nums)
    # Try all triplets: i, j, k (indices can be the same)
    for i in range(n):
        for j in range(n):
            for k in range(n):
                val = nums[i] ^ nums[j] ^ nums[k]
                seen.add(val)
    return len(seen)
